response:
**Gates before launch.** First I run `git log -- spe/plans/r04.md spe/predictions/r04.yaml` to confirm both files are committed and that no trial has run since then. Then I run three gates in order and halt on the first one that fails. Gate 1 is the grader selftest, `python spe/evals/graders/grade.py --selftest`. The oracle (answers.json fed back as output) must score 1.0 on all 50 tickets, and the empty and wrong answer sets must score 0. Round 3 used 40 tickets, so I also check that answers.json has a label for every ticket id in `args.tickets`. I also run judge.md once on a known polite reply and once on a known rude reply, and they must land on opposite sides of the pass line. Gate 2 is the control. I regrade round 3's saved outputs with this round's grade.py. If any round 3 number moves, the grader changed, not the agent, and I log that in spe/failures.md before going on. Gate 3 is a dry run of this script with `only: ["B:T001", "C2:T017", "C2:T042"]`, `trials: 1`, `topUpMaxTrials: 0`, and `spendCapUsd: 3`. It must return schema-valid trial rows, one grader row per trial, a leak scan that runs, and a judge score. After that I save the script as spe/evals/harness/r04-workflow.js and commit it locally with the gate output. The commit message is "spe r04: evaluate harness and gates", with no attribution lines. Then I launch with the full arguments and the $40 cap. I do not push.

**Defaults I chose.** Before launch, I export the 50 ticket texts without labels to spe/results/r04/tickets/. I pass each config's runner command in `args.configs`. That way trial agents never need to open spe/evals/.

```js
export const meta = {
  name: "triage-spe-round",
  description: "One SPE eval round for the triage agent. Runs every config on every ticket, grades labels with code, tops up split cells, judges reply tone with Opus, then runs failure analysis and a completeness critic.",
  phases: ["Trials", "Grade", "Top-up", "Judge", "Synthesis"]
};

// Round identity. Every prompt derives the round from these values.
const ROUND = args.round;                       // 4 for this run
const pad = (n) => `r${String(n).padStart(2, "0")}`;
const RID = pad(ROUND);
const NEXT = pad(ROUND + 1);

// Arguments. Every paid resource has a cap.
const CONFIGS = args.configs;                   // { B: { runner: "..." }, C2: { runner: "..." } }
const CFG_IDS = Object.keys(CONFIGS);
const TICKETS = args.tickets;                   // [{ id: "T001", path: "spe/results/r04/tickets/T001.txt" }]
const TRIALS = args.trials ?? 5;
const SPEND_CAP = args.spendCapUsd ?? 40;
const EST_TRIAL = args.estTrialUsd ?? 0.05;     // unmeasured estimate from the plan
const EST_JUDGE = args.estJudgeUsd ?? 0.15;     // unmeasured estimate from the plan
const TOPUP_PER_CELL = args.topUpPerCell ?? 5;
const TOPUP_CAP = args.topUpMaxTrials ?? 100;
const CONCURRENCY = args.concurrency ?? 10;
const AGENT_MODEL = args.agentModel ?? "opus";
const JUDGE_MODEL = args.judgeModel ?? "opus";
const OUT = args.outDir ?? `spe/results/${RID}/raw`;
const ONLY = args.only ?? null;                 // dry run, e.g. ["B:T001", "C2:T017"]

const FORBIDDEN = ["spe/evals/", "spe/predictions/"];
const GRADER = "spe/evals/graders/grade.py";
const ANSWERS = "spe/evals/tasks/answers.json";
const JUDGE_RUBRIC = "spe/evals/graders/judge.md";
const JUDGE_NOTE = "The tone judge is Opus, the same model family as the Sonnet trials. No judge from another family is available, so blind spots the two models share are not covered.";

// Cells
const cellKey = (cfg, tid) => `${cfg}:${tid}`;
let cells = [];
for (const cfg of CFG_IDS) for (const t of TICKETS) cells.push({ cfg, ticket: t, key: cellKey(cfg, t.id) });
if (ONLY) cells = cells.filter((c) => ONLY.includes(c.key));

// Budget. Reserve before each paid call, settle with the actual cost when known.
let spent = 0;
const skipped = [];
function reserve(usd, what) {
  if (spent + usd > SPEND_CAP) {
    skipped.push({ what, usd });
    log(`Skipped ${what}. Spend ${spent.toFixed(2)} plus ${usd} would cross the ${SPEND_CAP} USD cap.`);
    return false;
  }
  spent += usd;
  return true;
}
function settle(reserved, actual) {
  if (typeof actual === "number" && actual >= 0) spent += actual - reserved;
}

async function runLimited(thunks) {
  const out = [];
  for (let i = 0; i < thunks.length; i += CONCURRENCY) {
    out.push(...(await parallel(thunks.slice(i, i + CONCURRENCY))));
  }
  return out;
}

const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const median = (xs) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

function halt(reason, extra = {}) {
  log(`HALT: ${reason}`);
  return { round: RID, halted: true, reason, spent_usd: spent, cap_usd: SPEND_CAP, skipped, ...extra };
}

// Trials
const num = { type: "number" };
const TRIAL_SCHEMA = {
  type: "object",
  required: ["status", "category", "priority", "reply", "metrics", "commands"],
  properties: {
    status: { enum: ["completed", "harness_error", "rate_limited"] },
    error: { type: "string" },
    category: { type: ["string", "null"], enum: ["billing", "bug", "how-to", "account", "outage", null] },
    priority: { type: ["string", "null"], enum: ["P1", "P2", "P3", "P4", null] },
    reply: { type: "string" },
    metrics: {
      type: "object",
      required: ["runtime_s", "tool_calls", "tool_errors", "input_tokens", "output_tokens", "cost_usd"],
      properties: { runtime_s: num, tool_calls: num, tool_errors: num, input_tokens: num, output_tokens: num, cost_usd: num }
    },
    commands: { type: "array", items: { type: "string" } }
  }
};

const trialCount = {};
let trials = [];

function trialThunk(cell, phaseName) {
  return async () => {
    if (!reserve(EST_TRIAL, `${phaseName} trial ${cell.key}`)) return null;
    trialCount[cell.key] = (trialCount[cell.key] ?? 0) + 1;
    const n = trialCount[cell.key];
    const dir = `${OUT}/${cell.cfg}/${cell.ticket.id}/t${n}`;
    let r;
    try {
      r = await agent(
        `You run one trial of the triage agent for SPE ${RID}. You run it and report. You do not judge or fix it.

Run this one command from the repo root:
${CONFIGS[cell.cfg].runner} --ticket ${cell.ticket.path} --out ${dir}/output.json --transcript ${dir}/transcript.jsonl

Then read ${dir}/output.json and the metrics line at the end of ${dir}/transcript.jsonl.

Rules:
- You may read only ${cell.ticket.path}, ${dir}/output.json, and ${dir}/transcript.jsonl.
- Do not open, list, search, or print anything under ${FORBIDDEN.join(" or ")}.
- Do not edit any file. Do not rerun the command with changed flags.
- If the command fails, set status to harness_error. If it hits a rate limit, set status to rate_limited. Put the error text in error.
- List every shell command you ran in commands, exactly as typed.
- Copy category, priority, and reply from output.json without changes. Copy runtime_s, tool_calls, tool_errors, input_tokens, output_tokens, and cost_usd from the runner metrics.`,
        { label: `${cell.key} t${n}`, phase: phaseName, schema: TRIAL_SCHEMA, model: AGENT_MODEL }
      );
    } catch (e) {
      r = { status: "harness_error", error: String(e), commands: [], metrics: {} };
    }
    settle(EST_TRIAL, r?.metrics?.cost_usd);
    const leaks = (r?.commands ?? []).filter((c) => FORBIDDEN.some((p) => c.includes(p)));
    return { ...r, key: cell.key, cfg: cell.cfg, ticket: cell.ticket.id, trial: n, dir, leaks, voided: leaks.length > 0 };
  };
}

phase("Trials");
log(`${RID}: ${cells.length} cells x ${TRIALS} trials on ${CFG_IDS.join(", ")}. Spend cap ${SPEND_CAP} USD.${ONLY ? " Dry run." : ""}`);
{
  const thunks = [];
  for (const c of cells) for (let i = 0; i < TRIALS; i++) thunks.push(trialThunk(c, "Trials"));
  trials = (await runLimited(thunks)).filter(Boolean);
}

// Grade (code first)
const GRADE_SCHEMA = {
  type: "object",
  required: ["grader_ok", "rows"],
  properties: {
    grader_ok: { type: "boolean" },
    error: { type: "string" },
    rows: {
      type: "array",
      items: {
        type: "object",
        required: ["ticket", "trial", "category_ok", "priority_ok", "leak_hits"],
        properties: {
          ticket: { type: "string" },
          trial: { type: "integer" },
          category_ok: { type: "boolean" },
          priority_ok: { type: "boolean" },
          leak_hits: { type: "array", items: { type: "string" } }
        }
      }
    }
  }
};

function gradeConfig(cfg, phaseName) {
  return agent(
    `You run the code grader for SPE ${RID}, config ${cfg}. Do not change the grader, the answer file, or any trial output.

1. Run: python ${GRADER} --answers ${ANSWERS} --runs ${OUT}/${cfg} --json
2. For every trial folder under ${OUT}/${cfg}, search transcript.jsonl for any tool call, file read, or command that names ${FORBIDDEN.join(" or ")}. Put each hit in leak_hits for that trial.
3. Return one row per trial folder that has an output.json. Take ticket and trial from the path ${OUT}/${cfg}/<ticket>/t<n>.

If the grader exits non-zero or prints malformed JSON, set grader_ok to false, put the error text in error, and return no rows.`,
    { label: `grade ${cfg}`, phase: phaseName, schema: GRADE_SCHEMA, model: AGENT_MODEL }
  );
}

async function gradeAll(phaseName) {
  const results = await parallel(CFG_IDS.map((cfg) => () => gradeConfig(cfg, phaseName)));
  for (let i = 0; i < results.length; i++) {
    if (!results[i]?.grader_ok) return `grader failed on ${CFG_IDS[i]}: ${results[i]?.error ?? "no result"}`;
  }
  const rows = new Map();
  results.forEach((g, i) => g.rows.forEach((r) => rows.set(`${CFG_IDS[i]}:${r.ticket}:t${r.trial}`, r)));
  for (const t of trials) {
    if (t.status !== "completed") continue;
    const r = rows.get(`${t.cfg}:${t.ticket}:t${t.trial}`);
    if (!r) { t.status = "harness_error"; t.error = "grader returned no row"; continue; }
    t.category_ok = r.category_ok;
    t.priority_ok = r.priority_ok;
    t.leaks = [...new Set([...t.leaks, ...r.leak_hits])];
    t.voided = t.leaks.length > 0;
    t.pass = !t.voided && r.category_ok && r.priority_ok;
  }
  return null;
}

function leakHalt() {
  const leaked = trials.filter((t) => t.voided);
  if (!leaked.length) return null;
  return halt(`${leaked.length} trial(s) touched answer-key paths. They are void.`, {
    leaked: leaked.map((t) => ({ key: t.key, trial: t.trial, leaks: t.leaks }))
  });
}

phase("Grade");
{
  const err = await gradeAll("Grade");
  if (err) return halt(err);
  const h = leakHalt();
  if (h) return h;
}

// Top-up: replace harness errors, and add trials to split cells
phase("Top-up");
const byCell = () => {
  const m = new Map();
  for (const t of trials) { if (!m.has(t.key)) m.set(t.key, []); m.get(t.key).push(t); }
  return m;
};
{
  const groups = byCell();
  const thunks = [];
  let left = TOPUP_CAP;
  for (const c of cells) {
    const done = (groups.get(c.key) ?? []).filter((t) => t.status === "completed" && !t.voided);
    const passes = done.filter((t) => t.pass).length;
    const missing = Math.max(0, TRIALS - done.length);
    const split = passes > 0 && passes < done.length ? TOPUP_PER_CELL : 0;
    const want = Math.min(missing + split, left);
    if (want < missing + split) log(`Top-up cap reached. ${c.key} gets ${want} of ${missing + split} extra trials.`);
    left -= want;
    for (let i = 0; i < want; i++) thunks.push(trialThunk(c, "Top-up"));
  }
  log(`Top-up: ${thunks.length} extra trials. Cap ${TOPUP_CAP}.`);
  const extra = (await runLimited(thunks)).filter(Boolean);
  trials.push(...extra);
  if (extra.length) {
    const err = await gradeAll("Top-up");
    if (err) return halt(err);
    const h = leakHalt();
    if (h) return h;
  }
}

// Judge: tone only, because code cannot check it
phase("Judge");
log(JUDGE_NOTE);
const JUDGE_SCHEMA = {
  type: "object",
  required: ["scores"],
  properties: {
    scores: {
      type: "array",
      items: {
        type: "object",
        required: ["trial", "tone", "pass", "reason"],
        properties: {
          trial: { type: "integer" },
          tone: { type: "integer", minimum: 1, maximum: 5 },
          pass: { type: "boolean" },
          reason: { type: "string" }
        }
      }
    }
  }
};
{
  const groups = byCell();
  const thunks = cells.map((c) => async () => {
    const done = (groups.get(c.key) ?? []).filter((t) => t.status === "completed" && !t.voided);
    if (!done.length) return null;
    if (!reserve(EST_JUDGE, `judge ${c.key}`)) return null;
    const r = await agent(
      `You are the tone judge for SPE ${RID}. Read ${JUDGE_RUBRIC} and apply it exactly. Read the ticket at ${c.ticket.path}. Score the tone of each draft reply below. Judge tone only. Do not judge the category or the priority. Do not open any other file under spe/.

${done.map((t) => `--- trial ${t.trial} ---\n${t.reply}`).join("\n\n")}`,
      { label: `judge ${c.key}`, phase: "Judge", schema: JUDGE_SCHEMA, model: JUDGE_MODEL }
    );
    for (const s of r?.scores ?? []) {
      const t = done.find((x) => x.trial === s.trial);
      if (t) { t.tone = s.tone; t.tone_pass = s.pass; t.tone_reason = s.reason; }
    }
    return true;
  });
  await runLimited(thunks);
}

// Synthesis
phase("Synthesis");
function summarize(cfg) {
  const all = trials.filter((t) => t.cfg === cfg);
  const done = all.filter((t) => t.status === "completed" && !t.voided);
  const toned = done.filter((t) => typeof t.tone === "number");
  const m = (k) => done.map((t) => t.metrics?.[k]).filter((x) => typeof x === "number");
  return {
    config: cfg,
    completed: done.length,
    harness_errors: all.filter((t) => t.status === "harness_error").length,
    rate_limited: all.filter((t) => t.status === "rate_limited").length,
    voided: all.filter((t) => t.voided).length,
    category_acc: mean(done.map((t) => (t.category_ok ? 1 : 0))),
    priority_acc: mean(done.map((t) => (t.priority_ok ? 1 : 0))),
    both_acc: mean(done.map((t) => (t.pass ? 1 : 0))),
    tone_mean: mean(toned.map((t) => t.tone)),
    tone_pass_rate: mean(toned.map((t) => (t.tone_pass ? 1 : 0))),
    runtime_s_median: median(m("runtime_s")),
    tool_calls_mean: mean(m("tool_calls")),
    tool_errors_per_trial: mean(m("tool_errors")),
    tokens_mean: mean(done.map((t) => (t.metrics?.input_tokens ?? 0) + (t.metrics?.output_tokens ?? 0))),
    cost_usd_per_trial: mean(m("cost_usd"))
  };
}
const summary = CFG_IDS.map(summarize);
const failed = trials
  .filter((t) => t.status === "completed" && !t.voided && (!t.pass || t.tone_pass === false))
  .map((t) => ({ cfg: t.cfg, ticket: t.ticket, trial: t.trial, category: t.category, priority: t.priority,
    category_ok: t.category_ok, priority_ok: t.priority_ok, tone: t.tone, tone_reason: t.tone_reason }));
const errors = trials.filter((t) => t.status !== "completed").map((t) => ({ key: t.key, trial: t.trial, status: t.status, error: t.error }));

const ANALYSIS_SCHEMA = {
  type: "object",
  required: ["prediction_checks", "failure_patterns", "proposals", "saturated"],
  properties: {
    prediction_checks: { type: "array", items: { type: "object",
      required: ["metric", "config", "predicted", "band", "measured", "in_band", "scorable"],
      properties: { metric: { type: "string" }, config: { type: "string" }, predicted: num, band: num,
        measured: { type: ["number", "null"] }, in_band: { type: "boolean" }, scorable: { type: "boolean" } } } },
    failure_patterns: { type: "array", items: { type: "object", required: ["id", "tickets", "description", "likely_cause"],
      properties: { id: { type: "string" }, tickets: { type: "array", items: { type: "string" } },
        description: { type: "string" }, likely_cause: { type: "string" } } } },
    proposals: { type: "array", items: { type: "object", required: ["change", "reason"],
      properties: { change: { type: "string" }, reason: { type: "string" } } } },
    saturated: { type: "boolean" }
  }
};
const analysis = await agent(
  `You are the failure analyst for SPE ${RID} of the triage agent. Configs: ${CFG_IDS.join(", ")}. Do not edit any file.

Per-config results: ${JSON.stringify(summary)}
Failed trials: ${JSON.stringify(failed)}
Harness errors and rate limits (not model failures): ${JSON.stringify(errors)}
Skipped for budget: ${JSON.stringify(skipped)}

Read spe/predictions/${RID}.yaml, ${ANSWERS}, and spe/failures.md.
1. For each metric and config in the predictions file, give the predicted value, the band, the measured value, and whether the measured value is inside the band. If every config hit the maximum on a metric, mark it not scorable and set saturated to true.
2. Group the failed trials into patterns. Give each pattern an ID in the form "${RID} F<n>", the tickets it covers, and a likely cause tied to the difference between the configs.
3. Propose at most 3 changes for ${NEXT}. Each change alters one thing.`,
  { label: "failure analysis", phase: "Synthesis", schema: ANALYSIS_SCHEMA, model: AGENT_MODEL }
);

const critic = await agent(
  `You are the completeness critic for SPE ${RID}. Compare this run with the approved plan at spe/plans/${RID}.md. Do not edit any file. List every gap you find. Check these points:
- Every planned cell has ${TRIALS} completed trials, or a logged reason why not.
- Every metric in spe/predictions/${RID}.yaml has a measured number for each config.
- Skipped trials, harness errors, rate limits, and voided trials are counted and explained.
- The judge limitation is recorded: "${JUDGE_NOTE}"
- The failure analysis covers every failed trial.
- Spend stayed under the cap.

Run data: ${JSON.stringify({ planned_cells: cells.length, trials_per_cell: TRIALS, spent_usd: spent, cap_usd: SPEND_CAP, summary, skipped, errors, analysis })}`,
  { label: "completeness critic", phase: "Synthesis", model: AGENT_MODEL,
    schema: { type: "object", required: ["complete", "gaps"],
      properties: { complete: { type: "boolean" }, gaps: { type: "array", items: { type: "string" } } } } }
);

log(`${RID} done. Spent ${spent.toFixed(2)} of ${SPEND_CAP} USD. ${skipped.length} paid calls skipped. Critic complete: ${critic?.complete}.`);

return {
  round: RID,
  dry_run: Boolean(ONLY),
  spent_usd: spent,
  cap_usd: SPEND_CAP,
  skipped,
  judge_note: JUDGE_NOTE,
  summary,
  analysis,
  critic,
  trials: trials.map((t) => ({ key: t.key, trial: t.trial, status: t.status, error: t.error, category: t.category,
    priority: t.priority, category_ok: t.category_ok, priority_ok: t.priority_ok, pass: t.pass, voided: t.voided,
    tone: t.tone, tone_pass: t.tone_pass, metrics: t.metrics, dir: t.dir }))
};
```
